INSERT INTO `mdl_question_coderunner_options` VALUES
(1,1,'c_function',1,1,0,0,0,18,100,'','',1,'33.3, 66.7, ...','',0,NULL,NULL,'#include <stdio.h>\n#include <stdlib.h>\n#include <ctype.h>\n#include <string.h>\n#include <stdbool.h>\n#include <math.h>\n#define SEPARATOR \"#<ab@17943918#@>#\"\n\n{{ STUDENT_ANSWER }}\n\nint main() {\n{% for TEST in TESTCASES %}\n   {\n    {{ TEST.testcode }};\n   }\n    {% if not loop.last %}printf(\"%s\\n\", SEPARATOR);{% endif %}\n{% endfor %}\n    return 0;\n}',1,NULL,0,'|#<ab@17943918#@>#\\n|ms',NULL,'','twig',0,'',0,1,0,'','C',NULL,NULL,'{\"linkargs\": [\"-lm\"]}','EqualityGrader',NULL,NULL,'ace',0,0,0,'','',0,0,NULL),
(2,2,'cpp_function',1,1,0,0,0,18,100,'','',1,'33.3, 66.7, ...','',0,NULL,NULL,'#include <iostream>\n#include <fstream>\n#include <string>\n#include <cmath>\n#include <vector>\n#include <algorithm>\n\nusing namespace std;\n#define SEPARATOR \"#<ab@17943918#@>#\"\n\n{{ STUDENT_ANSWER }}\n\nint main() {\n{% for TEST in TESTCASES %}\n   {\n    {{ TEST.extra }};\n    {{ TEST.testcode }};\n   }\n    {% if not loop.last %}cout << SEPARATOR << endl;{% endif %}\n{% endfor %}\n    return 0;\n}',1,NULL,0,'|#<ab@17943918#@>#\\n|ms',NULL,'','twig',0,'',0,1,0,'','cpp',NULL,NULL,'{\"linkargs\": [\"-lm\"]}','EqualityGrader',NULL,NULL,'ace',0,0,0,'','',0,0,NULL),
(3,3,'cpp_program',1,1,0,0,0,18,100,'','',1,'33.3, 66.7, ...','',0,NULL,NULL,'{{ STUDENT_ANSWER }}',0,NULL,0,NULL,NULL,'','twig',0,'',0,1,0,'','cpp',NULL,NULL,'{\"linkargs\": [\"-lm\"]}','EqualityGrader',NULL,NULL,'ace',0,0,0,'','',0,0,NULL),
(4,4,'c_program',1,1,0,0,0,18,100,'','',1,'33.3, 66.7, ...','',0,NULL,NULL,'{{ STUDENT_ANSWER }}',0,NULL,0,NULL,NULL,'','twig',0,'',0,1,0,'','C',NULL,NULL,'{\"linkargs\": [\"-lm\"]}','EqualityGrader',NULL,NULL,'ace',0,0,0,'','',0,0,NULL),
(5,5,'directed_graph',1,1,0,0,0,18,100,'','',1,'10, 20, ...','',0,NULL,NULL,'import json\n\nstudent_answer = \"\"\"{{ STUDENT_ANSWER | e(\'py\') }}\"\"\"\nSEPARATOR = \"#<ab@17943918#@>#\"\n\nerror_count = 0\ndef error(s):\n    global error_count\n    print(s)\n    error_count += 1\n\ntry:\n    graph_rep = json.loads(student_answer)\n    node_id_to_name_map = {}\n    for i, node in enumerate(graph_rep[\'nodes\']):\n        name_stripped = node[0].strip()\n        node_id_to_name_map[i] = name_stripped if name_stripped != \'\' else (\'#\' + str(i))\n    #print(\"Nodes:\", nodes)\n    edges = graph_rep[\'edges\']\n    #print(\"Edges:\", edges)\n    graph = {}\n    for node_id, node_name in sorted(node_id_to_name_map.items()):\n        edges = []\n        for id0, id1, edge_label, *loc in graph_rep[\'edges\']:\n            if id0 == node_id:\n                edges.append((node_id_to_name_map[id1], edge_label.strip()))\n        edges.sort()\n        graph[node_name] = edges\n\nexcept json.JSONDecodeError as e:\n    raise Exception(\"Oops. Illegal graph received (exception {}). Please report (unless you did something silly yourself)\".format(e))\n\n{% for TEST in TESTCASES %}\n{# note: also check unhoisted variable name in case someone turned off hoisting #}\n{% if extra == \"pretest\" or QUESTION.parameters.extra == \"pretest\" %}\n{{TEST.extra}}\n{% endif %}\n{{TEST.testcode}}\n{# note: also check unhoisted variable name in case someone turned off hoisting #}\n{% if extra == \"posttest\" or QUESTION.parameters.extra == \"posttest\" %}\n{{TEST.extra}}\n{% endif %}\n{% if not loop.last %}\nprint(SEPARATOR)\n{% endif %}\n{% endfor %}',1,NULL,0,'|#<ab@17943918#@>#\\n|ms',NULL,'{\"extra\":\"posttest\"}','twig',0,'{\"extra\":\"posttest\"}',1,1,0,'{\"isdirected\": true, \"isfsm\": false}','python3',NULL,NULL,NULL,'EqualityGrader',NULL,NULL,'graph',0,0,0,'','',0,0,NULL),
(6,6,'java_class',1,1,0,0,0,18,100,'','',1,'33.3, 66.7, ...','',0,NULL,NULL,'{{ STUDENT_ANSWER | replace({\'public class \': \'class \'}) }}\n\npublic class __tester__ {\n\n    public static void main(String[] args) {\n        __tester__ main = new __tester__();\n        main.runTests();\n    }\n\n    public void runTests() {\n        {{ TEST.testcode }};\n    }\n}\n',0,NULL,0,NULL,NULL,'','twig',0,'',0,1,0,'','Java',NULL,NULL,NULL,'EqualityGrader',NULL,2000,'ace',0,0,0,'','',0,0,NULL),
(7,7,'java_method',1,1,0,0,0,18,100,'','',1,'33.3, 66.7, ...','',0,NULL,NULL,'public class __tester__ {\n    static String SEPARATOR = \"#<ab@17943918#@>#\";\n    {{ STUDENT_ANSWER }}\n\n    public static void main(String[] args) {\n        __tester__ main = new __tester__();\n        main.runTests();\n    }\n\n    public void runTests() {\n{% for testCase in TESTCASES %}\n    {\n    {{ testCase.testcode }};\n    {% if not loop.last %}\n    System.out.println(SEPARATOR);\n    {% endif %}\n    }\n{% endfor %}\n    }\n}',1,NULL,0,'|#<ab@17943918#@>#\\n|ms',NULL,'','twig',0,'',0,1,0,'','Java',NULL,NULL,NULL,'EqualityGrader',NULL,2000,'ace',0,0,0,'','',0,0,NULL),
