(23,23,'cpp_function',0,1,0,0,0,18,100,'','',NULL,'0','int IsPrime(int n) {\n    if (n <= 1)\n        return 0;  // 0 and 1 are not prime\n\n    for (int i = 2; i <= sqrt(n); i++) {\n        if (n % i == 0)\n            return 0;  // Not prime if divisible by i\n    }\n\n    return 1;  // Prime if not divisible by any number from 2 to n/2\n}\n\nvoid ArrPrimes(int A[], int n)\n{\n    int count = 0;\n    for(int i = 0; i < n; i++){\n        if(IsPrime(A[i])) {\n            \n            if(count == 10) {printf(\"\\n\"); count = 0;}\n            printf(\"%d \",A[i]);\n            count = count + 1;\n        }\n    }\n    \n}\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,0,NULL),
(24,24,'c_function',0,1,0,0,0,18,100,'','',NULL,'0','int IsPerfectSquare(int number) {\n    int i;\n    \n    for (i = 1; i * i <= number; i++) {\n        if (number % i == 0 && number / i == i)\n            return 1;\n    }\n    \n    return 0;\n}\n\nint ArrPerfects(int A[], int n)\n{\n    int sum = 0;\n    for(int i = 0; i < n; i++){\n        if(IsPerfectSquare(A[i])) {\n            sum = sum + A[i];            \n        }\n    }\n    return sum;\n}\n\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,2,NULL),
(25,25,'c_function',0,1,0,0,0,18,100,'','',NULL,'0','int IsSymmetrical(int number) {\n    int reverse = 0;\n    int original = number;\n    \n    while (number > 0) {\n        reverse = (reverse * 10) + (number % 10);\n        number /= 10;\n    }\n    \n    return (original == reverse);\n}\n\nint ArrCountSymmetric(int A[], int n)\n{\n    int count= 0;\n    for(int i = 0; i < n; i++){\n        if(IsSymmetrical(A[i])) {\n            count= count+ 1;            \n        }\n    }\n    return count;\n}',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,0,NULL),
(26,26,'c_function',0,1,0,0,0,18,100,'','',NULL,'0','int SumDigitsDivisibleBy3(int number) {\n    int sum = 0;\n    number = abs(number);    \n    while (number > 0) {\n        sum += number % 10;\n        number /= 10;\n    }\n    \n    return (sum % 3 == 0);\n}\n\nint ArrCount_SumDigitsDivisibleBy3 (int A[], int n)\n{\n    int count= 0;\n    for(int i = 0; i < n; i++){\n        if(SumDigitsDivisibleBy3(A[i])) {\n            count= count+ 1;            \n        }\n    }\n    return count;\n}\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,0,NULL),
(27,27,'c_function',0,1,0,0,0,18,100,'','',NULL,'0','double ArrMax(double A[], int n)\n{\n    double max = A[0];\n    for(int i = 1; i < n; i++){\n        if(max <= A[i]) max = A[i];\n    }\n    return max;\n}\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,0,NULL),
(28,28,'c_function',0,1,0,0,0,18,100,'','',NULL,'0','int ArrFindK(int A[], int n, int K)\n{\n    for(int i = 0; i < n; i++){\n        if(A[i] == K) return i;\n    }\n    return -1;\n}\n\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,0,NULL),
(29,29,'c_function',0,1,0,0,0,18,100,'','',NULL,'0','int ArrEvenMax(int A[], int n)\n{\n    int max = -8080;\n    for(int i = 0; i < n; i++){\n        if(A[i] % 2 == 0 && A[i] > max){\n            max = A[i];\n        }\n    }\n    return max;\n}\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,0,NULL),
(30,30,'c_function',0,1,0,0,0,18,100,'','',NULL,'0','void ArrMostOccurence(int A[], int size)\n{\n    int maxElement = A[0]; // Keeps track of the element with maximum count\n    int maxCount = 1; // Keeps track of the maximum count\n\n    // Traverse the input array\n    for (int i = 0; i < size - 1; i++) {\n        int currentElement = A[i];\n        int currentCount = 1;\n\n        // Count the occurrences of the current element\n        for (int j = i + 1; j < size; j++) {\n            if (A[j] == currentElement)\n                currentCount++;\n        }\n\n        // Update the maximum count and element if necessary\n        if (currentCount > maxCount) {\n            maxCount = currentCount;\n            maxElement = currentElement;\n        }\n    }\n\n    printf(\"%d %d\", maxElement,maxCount);    \n}',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,0,NULL),
(31,31,'c_function',0,1,0,0,0,18,100,'','',NULL,'0','int FindKthOddArray(int A[], int size, int k)\n{\n    int count = 0;\n    for(int i = 0; i < size; i++)\n        if(A[i] % 2 == 1) \n        {\n            count++;\n            if(count == k) return A[i];\n        }\n    return -1;\n}',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,0,NULL),
(32,32,'c_function',0,1,0,0,0,18,100,'','',NULL,'0','#include<math.h>\ndouble ArrDistanceEuclid(double A[], double B[], int n)\n{\n    double d = 0;\n    for(int i = 0;  i < n; i++){\n        d += (A[i] - B[i])*(A[i] - B[i]);\n    }\n    return sqrt(d);\n}\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,0,NULL),
(33,33,'c_function',0,1,0,0,0,18,100,'','',NULL,'0','void ArrMerge(int A1[], int n1, int A2[], int n2, int A3[], int n3)\n{    \n    int i = 0, j = 0, k = 0;\n    while(i < n1 && j < n2){\n        if(A1[i] < A2[j]){\n            A3[k] = A1[i];\n            i++;\n        }\n        else{\n            A3[k] = A2[j];\n            j++;\n        }\n        k++;\n    }\n    \n    //printf(\"%d %d %d\\n\", i,j,k);\n    for(int l = i; l < n1; l++, k++) A3[k] = A1[l];      \n    for(int l = j; l < n2; l++, k++) A3[k] = A2[l];  \n    for(int i = 0; i < n1+n2; i++) printf(\"%d \",A3[i]);    \n}',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,0,NULL),
(34,34,'c_function',0,1,0,0,0,18,100,'','',NULL,'0','void ArrFrequency(int A[], int n)\n{\n    int B[10000] ;\n    for(int i = 0; i < n; i++){\n        B[i] = 0;\n    }\n    printf(\"Value\\tFrequency\\n\");\n    for(int i = 0; i < n; i++){\n        if(B[i] == 0){\n            int count = 1;\n            B[i] = 1;\n            for(int j = i + 1; j < n; j++){\n                if(A[i] == A[j] && B[j] == 0){\n                    count = count + 1;\n                    B[j] = 1;\n                } \n            }\n            printf(\"%d\\t%d\\n\",A[i],count);\n        }\n        \n    }\n}',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,0,NULL),
