(38,38,'c_program',0,1,0,0,0,18,100,'','',NULL,'0','#include <stdio.h>\n\nint main()\n{\n    int kwhs;\n    scanf(\"%d\",&kwhs);\n    if(kwhs <= 100) printf(\"%d\",kwhs*950);\n    else if(kwhs <= 150) printf(\"%d\",100*950+(kwhs-100)*1250);\n        else if(kwhs <= 200) printf(\"%d\",100*950+50*1250+(kwhs-150)*1350);\n            else printf(\"%d\",100*950+50*1250+50*1350+(kwhs-200)*1550);\n        \n    return 0;\n}',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,0,NULL),
(39,39,'c_program',0,1,0,0,0,18,100,'','',NULL,'0','#include <stdio.h>\n\nint main()\n{\n    int year;\n    scanf(\"%d\", &year);\n    if(year % 4 == 0) \n        if (year % 100 == 0 && year % 400 != 0) printf(\"NOT a Leap Year\");\n        else printf(\"Leap Year\");\n    else printf(\"NOT a Leap Year\");\n        \n    return 0;\n}',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,0,NULL),
(40,40,'c_program',0,1,0,0,0,18,100,'','',NULL,'0','#include <stdio.h>\n\nint main()\n{\n    int month, year;\n    scanf(\"%d%d\", &month, &year);\n    if(month > 12 || month < 1) printf(\"Nhap sai\");\n    else \n        if(year % 4 == 0 && month == 2) \n            if (year % 100 == 0 && year % 400 != 0) printf(\"28\");\n            else printf(\"29\");\n        else if(month == 2) printf(\"28\");\n            else if(month == 1 || month == 3 || month == 5 || month == 7 || month == 8 || month == 10 || month == 12) printf(\"31\");\n                else printf(\"30\");\n\n        \n    return 0;\n}',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,0,NULL),
