(42,42,'c_program',0,1,0,0,0,18,100,'','',NULL,'0','#include <stdio.h>\n\nint main()\n{\n        int a,b,c,d,x,y;\n    scanf(\"%d%d%d%d\", &a, &b, &c, &d);\n    x = a;\n    y = c;\n    if(a < b) x = b;\n    if(c < d) y = d;\n    if(x<y) x = y;\n    printf(\"Max number is %d\",x);\n    return 0;\n}',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,0,NULL),
(43,43,'c_program',0,1,0,0,0,18,100,'','',NULL,'0','#include <stdio.h>\n\nint IsLeapYear(int year)\n{\n    if(year % 4 == 0) \n        if (year % 100 == 0 && year % 400 != 0) return 0;\n            else return 1;\n    else return 0;\n}\nint main()\n{\n    int d, m, y;\n    int dp, mp, yp;\n    //int dt, mt, yt;\n    int leap = 1;\n    scanf(\"%d%d%d\",&d,&m,&y);\n    \n    printf(\"Day\\tMonth\\tCurrent day\\tYesterday\\n\");\n    printf(\"%d\\t%d\\t\",d,m);\n    printf(\"%d/%d/%d\\t\",d,m,y);\n    dp = d - 1;\n    mp = m;\n    yp = y;\n    if(d == 1){\n        mp = m - 1;\n        \n        switch(mp){\n            case 2:\n                if(leap == IsLeapYear(yp)) dp = 29;\n                else dp = 28;\n                \n                break;\n            case 0:\n                mp = 12;\n                yp = yp - 1;\n            case 1:\n            case 3:\n            case 5:\n            case 7:\n            case 8:\n            case 10:\n            case 12:\n                dp = 31;\n                break;\n            case 4:\n            case 6:\n            case 9:\n            case 11:\n                dp = 30;    \n        }\n                \n    }\n    //Yesterday\n    printf(\"%d/%d/%d\\t\",dp,mp,yp);\n    // Tomorrow\n    printf(\"%d/%d/%d\",d,m,y);\n\n    return 0;\n}',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,0,NULL),
(44,44,'c_program',0,1,0,0,0,18,100,'','',NULL,'0','#include <stdio.h>\nint IsLeapYear(int year)\n{\n    if(year % 4 == 0) \n        if (year % 100 == 0 && year % 400 != 0) return 0;\n            else return 1;\n    else return 0;\n}\nint main()\n{\n    int d, m, y;\n    int dt, mt, yt;\n    int leap = 1;\n    scanf(\"%d%d%d\",&d,&m,&y);\n    \n    printf(\"Day\\tMonth\\tCurrent day\\tTomorrow\\n\");\n    printf(\"%d\\t%d\\t\",d,m);\n    printf(\"%d/%d/%d\\t\",d,m,y);\n    \n    \n    // Tomorrow\n    dt = d + 1;\n    mt = m ;\n    yt = y;\n    switch(m){\n        \n        case 2:\n                if(leap == IsLeapYear(y)){ \n                    if(d == 29) {dt = 1, mt = m + 1;}}\n                else  if(d == 28) { dt = 1, mt = m + 1;};\n                break;\n        case 13:\n                mt = 1;\n                yt = yt + 1;\n        case 1:\n        case 3:\n        case 5:\n        case 7:\n        case 8:\n        case 10:\n        case 12:\n             if(d == 31 ){\n                if(m == 12){dt = 1, mt= 1; yt = yt + 1;}\n                else {dt = 1; mt= m+1;}    \n            }\n            break;\n        case 4:\n        case 6:\n        case 9:\n        case 11:\n            if(d == 30 && m == 12) {dt = 1, mt = m + 1;}\n            else dt = 1;\n        }\n    printf(\"%d/%d/%d\",dt,mt,yt);\n\n    return 0;\n}',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,0,NULL),
(45,45,'c_program',0,1,0,0,0,18,100,'','',NULL,'0','#include <stdio.h>\n\nint main()\n{\n        int number;\n    scanf(\"%d\", &number);\n    int digit;\n    if(number >= 10){\n        digit = number / 10;        \n        switch(digit)\n        {\n            \n            case 1: printf(\"muoi \");\n            break;\n            case 2: printf(\"hai muoi \");\n            break;\n            case 3: printf(\"ba muoi \");\n            break;\n            case 4: printf(\"bon muoi \");\n            break;\n            case 5: printf(\"nam muoi \");\n            break;\n            case 6: printf(\"sau muoi \");\n            break;\n            case 7: printf(\"bay muoi \");\n            break;\n            case 8: printf(\"tam muoi \");\n            break;\n            case 9: printf(\"chin muoi \");\n        }\n        if(number%10 == 5) {printf(\"lam\");}\n        else number = number % 10;\n    }\n    //else if (number == 5) printf(\"nam\");\n            \n    if(number >= 1)\n        switch(number)\n        {\n            case 0: printf(\"khong\");\n            break;\n            case 1: printf(\"mot\");\n            break;\n            case 2: printf(\"hai\");\n            break;\n            case 3: printf(\"ba\");\n            break;\n            case 4: printf(\"bon\");\n            break;\n            case 5: printf(\"nam\");\n            break;\n            case 6: printf(\"sau\");\n            break;\n            case 7: printf(\"bay\");\n            break;\n            case 8: printf(\"tam\");\n            break;\n            case 9: printf(\"chin\");\n        }\n\n\n    return 0;\n}',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,0,NULL),
