(47,47,'c_program',0,1,0,0,0,18,100,'','',NULL,'0','#include <stdio.h>\n\nint main()\n{\n    \n    char letter;\n    printf(\"letter = \");\n    scanf(\"%c\",&letter);\n    switch(letter){\n        case \'a\':\n        case \'A\':\n            printf(\"%d: A\", \'A\');\n            break;\n        case \'e\':\n        case \'E\':\n            printf(\"%d: E\", \'E\');\n            break;\n        case \'i\':\n        case \'I\':\n            printf(\"%d: I\", \'I\');\n            break;\n        case \'o\':\n        case \'O\':\n            printf(\"%d: O\", \'O\');\n            break;\n        case \'u\':\n        case \'U\':\n            printf(\"%d: U\", \'U\');\n            break;\n        case \'y\':\n        case \'Y\':\n            printf(\"%d: Y\", \'Y\');\n            break;\n        default:\n            printf(\"%d: %c is not a vowel\", letter,letter);\n        \n    }\n    return 0;\n}',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,0,NULL),
(48,48,'c_function',0,1,0,0,0,18,100,'','',NULL,'0','float BMI(int weight, float height)\n{\n    return weight/(height*height);\n}\n\nvoid Obese(float bmi)\n{\n    if(bmi < 18.5) printf(\"Underweight\");\n    else if(bmi < 23) printf(\"Normal weight\");\n        else if(bmi < 25) printf(\"Overweight\");\n            else printf(\"Obese\");\n}\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,0,NULL),
(49,49,'c_function',0,1,0,0,0,18,100,'','',NULL,'0','int Perfect(int n)\n{\n    int sum = 0;\n    for(int i = 1; i <= n/2; i++)\n    {\n        if(n%i==0){\n            sum += i;\n        }\n    }\n    sum += n;\n    if(sum == 2*n) return 1;\n    return 0;\n\n}\n\nvoid AllPerfect(int n)\n{\n    for(int i = 1; i<=n; i++){\n        int p = Perfect(i);\n        if(p) printf(\"%d \",i);    \n    }\n}\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,0,NULL),
