(51,51,'c_function',0,1,0,0,0,18,100,'void Calculator(int a, int b, char opt)\n{\n    //CODE HERE\n\n\n}','',NULL,'0','void Calculator(int a, int b, char opt)\n{\n    switch(opt){\n        case \'+\': printf(\"%d\", a+b); break;\n        case \'-\': printf(\"%d\", a-b);break;\n        case \'*\': printf(\"%d\", a*b);break;\n        case \'/\': printf(\"%.2f\", (float)a/b);break;\n        default: printf(\"Not Existing\");\n    }\n}',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,0,NULL),
(52,52,'c_function',0,1,0,0,0,18,100,'void Division(int n, int op)\n{\n   //CODE HERE\n\n\n}','',NULL,'0','int SumDigits(int n)\n{\n    int sum = 0;\n    for(int i = n; i > 0; i /= 10)\n    {\n        sum += i % 10;\n    }\n    return sum;\n}\n\nvoid ShowYN(int v)\n{\n    if(v) printf(\"Yes\");\n        else printf(\"No\");\n}\nint RightN(int n)\n{\n    return n%10;\n}\n\nint Div2(int n)\n{\n    return n%2==0?1:0;\n}\n\nint Div3(int n)\n{\n    return n%3==0?1:0;\n}\n\nint Div5(int n)\n{\n    return n%5==0?1:0;\n}\n\nint Div6(int n)\n{\n    return n%6==0?1:0;\n}\n\nint Div9(int n)\n{\n    return n%9==0?1:0;\n}\n\nvoid DivAll(int n)\n{\n    int v;\n    printf(\"Div\\tYes/No\\n\");\n    v = Div2(n);\n    printf(\"%d\\t\",2);\n    ShowYN(v);\n    printf(\"\\n\");\n    v = Div3(n);\n    printf(\"%d\\t\",3);\n    ShowYN(v);\n    printf(\"\\n\");\n    v = Div5(n);\n    printf(\"%d\\t\",5);\n    ShowYN(v);\n    printf(\"\\n\");\n    v = Div6(n);\n    printf(\"%d\\t\",6);\n    ShowYN(v);\n    printf(\"\\n\");\n    v = Div9(n);\n    printf(\"%d\\t\",9);\n    ShowYN(v);\n    printf(\"\\n\");\n}\n\nvoid Division(int n, int op)\n{\n    int v;\n    switch(op){\n    case 1:\n        v = SumDigits(n);\n        printf(\"Sum of digits = %d\",v);\n        break;\n    case 2:\n        v = RightN(n);\n        printf(\"Right N = %d\",v);\n        break;\n    case 3:\n        v = Div2(n);\n        ShowYN(v);\n        break;\n    case 4:\n        v = Div3(n);\n        ShowYN(v);\n        break;\n    case 5:\n        v = Div5(n);\n        ShowYN(v);\n        break;\n    case 6:\n        v = Div6(n);\n        ShowYN(v);\n        break;\n    case 7:\n        v = Div9(n);\n        ShowYN(v);\n        break;\n    case 8:\n        DivAll(n);\n        break;\n    default:\n        break;\n    }\n}',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,0,NULL),
(53,53,'c_function',0,1,0,0,0,18,100,'void SumN(int N)\n{\n   // CODE HERE\n}','',NULL,'0','void SumN(int N)\n{\n  int i = 1, S = 0;\n  while(i<= N)\n    {\n      S = S + i;\n      i++;\n    }\n  printf(\"%d\", S);\n}\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,0,NULL),
