(56,56,'c_function',0,1,0,0,0,18,100,'','',NULL,'0','void FindMaxN(int S)\n{\n    int i = 1, sum = 0; \n    while(sum + i < S){\n        sum += i;\n        i++;\n    }\n    if(sum > 0) printf(\"%d %d\",i-1, sum);\n    else printf(\"Not found!\");\n    \n}\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,0,NULL),
(57,57,'c_function',0,1,0,0,0,18,100,'','',NULL,'0','#include<stdio.h>\nvoid IsPrime(int n) {\n    int b = 1;\n    if (n <= 1)\n        printf(\"%d is not prime!\", n);  // 0 and 1 are not prime\n    else{\n        for (int i = 2; i <= n/2; i++) {\n            if (n % i == 0){\n                printf(\"%d is not prime!\", n);  // Not prime if divisible by i\n                b = 0;\n                break;\n            }\n        }\n    if(b == 1)    printf(\"%d is prime!\", n);  // Prime if not divisible by any number from 2 to n/2\n    }\n}\n\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,0,NULL),
(58,58,'c_function',0,1,0,0,0,18,100,'long unsigned int Factorial(int k)\n{\n   //CODE HERE\n\n   return 0;\n}','',NULL,'0','long unsigned int Factorial(int k)\n{\n    long unsigned int p = 1;\n    for(int i = k; i >= 1; i--){\n        p *= i;\n    }\n    return p;\n}\n\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,0,NULL),
(59,59,'c_function',0,1,0,0,0,18,100,'','',NULL,'0','double Facorial(int n)\r\n{\r\n	if(n==0) return 1;\r\n	else return Facorial(n-1)*n;\r\n}\r\n// Tinh e mu x\r\ndouble Cosx(float x,float err)\r\n{\r\n	double s=1;\r\n	int n=1;\r\n	while (1)\r\n	{\r\n	    double res = pow(-1,n)*pow(x,2*n)/Facorial(2*n);\r\n	    if(fabs(res) < err) break;\r\n		s=s+res;\r\n		n++;\r\n	}\r\n	return s;\r\n}',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,0,NULL),
(60,60,'c_function',0,1,0,0,0,18,100,'','',NULL,'0','double Facorial(int n)\r\n{\r\n	if(n==0) return 1;\r\n	else return Facorial(n-1)*n;\r\n}\r\n\r\ndouble Sinx(float x,float err)\r\n{\r\n	double s=1;\r\n	int n=1;\r\n	while (fabs(pow(-1,n)*pow(x,2*n+1)/Facorial(2*n+1))>=err)\r\n	{\r\n		s=s+pow(-1,n)*pow(x,2*n+1)/Facorial(2*n+1);\r\n		n++;\r\n	}\r\n	return s;\r\n}\r\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,0,NULL),
(61,61,'c_function',0,1,0,0,0,18,100,'','',NULL,'0','double Facorial(int n)\n{\n	if(n==0) return 1;\n	else return Facorial(n-1)*n;\n}\n\ndouble Emux(float x,float err)\n{\n	double s=1;\n	int n=1;\n	while (1)\n	{\n	    double res = pow(x,n)/Facorial(n);\n	    if(fabs(res)<err) break;\n		s=s+res;\n		n++;\n	}\n	return s;\n}',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,0,NULL),
(62,62,'c_function',0,1,0,0,0,18,100,'','',NULL,'0','int IsPrime(int n) {\n    if (n <= 1)\n        return 0;  // 0 and 1 are not prime\n\n    for (int i = 2; i <= sqrt(n); i++) {\n        if (n % i == 0)\n            return 0;  // Not prime if divisible by i\n    }\n\n    return 1;  // Prime if not divisible by any number from 2 to n/2\n}\n\nvoid AllPrimes(int n) {\n    // Print all prime numbers\n    int p;\n    for (p = 2; p <= n; p++) {\n        if (IsPrime(p))\n            printf(\"%d \", p);\n    }\n    printf(\"\\n\");\n}',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,0,NULL),
