(96,96,'c_program',0,1,0,0,0,18,100,'','',NULL,'0','#include <stdio.h>\n\nint main()\n{\n    int fh =500, th=200, oh=100, ft=50;\n    int m;\n    scanf(\"%d\",&m);\n    for(int i = 0; i*fh <= m; i++ )\n    {\n        for(int j = 0; j*th <= m; j++){\n            for(int k = 0; k*oh <= m; k++){\n                for(int l = 0; l*ft <= m; l++)\n                if(i*fh + j*th + k*oh + l*ft == m) printf(\"%d to %d + %d to %d + %d to %d + %d to %d\\n\", i, fh,j,th,k,oh,l,ft);\n            }\n            \n        }\n    }\n\n    return 0;\n}',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,0,NULL),
