(108,108,'c_function',0,1,0,0,0,18,100,'','',NULL,'0','int ThreeofEvenDigits(int n)\n{\n    int count = 0;\n    for(int i = n; i > 0; i/=10)\n    {\n        int d = i%10;\n        if(d % 2 == 0) count++;\n        else return 0;\n    }\n    if(count == 3) return 1;\n    return 0;\n}\nint MatrixEvenTribleEle(int M[][20], int n ,int m)\n{\n    int count = 0;\n    for(int i = 0; i < n; i++){\n        for(int j = 0; j < m; j++){\n            int v = ThreeofEvenDigits(M[i][j]);\n            if(v) count++;\n        }\n    }\n    return count;\n}\n',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,0,NULL),
(109,109,'c_function',0,1,0,0,0,18,100,'','',NULL,'0','int MatrixSumEven(int M[][20], int n ,int m)\n{\n    int sum = 0;\n    for(int i = 0; i < n; i++){\n        for(int j = 0; j < m; j++){\n            if(M[i][j]%2==0) sum = sum + M[i][j];\n        }\n    }\n    return sum;\n}',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,0,NULL),
