(112,112,'c_function',0,1,0,0,0,18,100,'','',NULL,'0','void MatrixTranspose(float A[100][100], float B[100][100], int n, int m)\n{\n    for(int i = 0; i < n; i++){\n        for(int j = 0; j < m; j++){\n            B[j][i] = A[i][j];\n        }\n    }\n}\n\nvoid MatrixShow(float M[100][100], int n, int m)\n{\n    for(int i = 0; i < n; i++)\n    {\n        for(int j = 0; j < m; j++){\n            printf(\"%.2f \", M[i][j]);\n        }\n        printf(\"\\n\");\n    }\n}',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,0,NULL),
(113,113,'c_function',0,1,0,0,0,18,100,'','',NULL,'0','void MatrixAddition(float A[100][100], float B[100][100], float C[100][100], int n, int m)\n{\n    \n    for(int i = 0; i < n; i++){\n        for(int j = 0; j < m; j++){\n            C[i][j] = A[i][j] + B[i][j];\n        }\n    }\n}\n\nvoid MatrixShow(float M[100][100], int n, int m)\n{\n    for(int i = 0; i < n; i++)\n    {\n        for(int j = 0; j < m; j++){\n            printf(\"%.2f \", M[i][j]);\n        }\n        printf(\"\\n\");\n    }\n}',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,0,NULL),
(114,114,'c_function',0,1,0,0,0,18,100,'','',NULL,'0','void MatrixMultiply(float A[100][100], float B[100][100], float C[100][100], int n, int k, int m)\n{\n    for(int i = 0; i < n; i++){\n        \n        for(int j = 0; j < m; j++){\n            float sum = 0;\n            for(int l = 0; l < k; l++)\n                sum = sum + A[i][l]*B[l][j];\n            C[i][j] = sum;\n        }\n    }\n}\n\nvoid MatrixShow(float M[100][100], int n, int m)\n{\n    for(int i = 0; i < n; i++)\n    {\n        for(int j = 0; j < m; j++){\n            printf(\"%.2f \", M[i][j]);\n        }\n        printf(\"\\n\");\n    }\n}',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,0,NULL),
(115,115,'c_function',0,1,0,0,0,18,100,'','',NULL,'0','void MatrixShow(float M[100][100], int n, int m)\n{\n    for(int i = 0; i < n; i++)\n    {\n        for(int j = 0; j < m; j++){\n            printf(\"%.2f \", M[i][j]);\n        }\n        printf(\"\\n\");\n    }\n}\n\nvoid MatrixScalar(float M[100][100], float c, int n, int m)\n{\n    for(int i = 0; i < n; i++)\n    {\n        for(int j = 0; j < m; j++){\n            M[i][j] = M[i][j]*c;\n        }\n    }\n}',1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,10240,'','',1,0,NULL),
