(117,117,'c_function',0,1,0,0,0,18,100,'void DisplayVertRecsion(int number)\n{\n    // CODE HERE\n\n\n}\n','',NULL,'0','void DisplayVertRecsion(int number)\n{\n    if(number < 10) printf(\"%d\\n\",number);\n    else{\n        DisplayVertRecsion(number/10);\n        printf(\"%d\\n\",number%10);\n    }\n}\n',1,NULL,NULL,'#include <stdio.h>\n#include <stdlib.h>\n#include <ctype.h>\n#include <string.h>\n#include <stdbool.h>\n#include <math.h>\n#define SEPARATOR \"#<ab@17943918#@>#\"\n\n{{ STUDENT_ANSWER }}\n\nint main() {\n    {% if \'for\' in STUDENT_ANSWER %}\n        printf(\"You have include for\");\n        return 1;\n    {% endif %}\n    {% if \'while\' in STUDENT_ANSWER %}\n        printf(\"You have include while\");\n        return 1;\n    {% endif %}\n\n{% for TEST in TESTCASES %}\n   {\n    {{ TEST.testcode }};\n   }\n    {% if not loop.last %}printf(\"%s\\n\", SEPARATOR);{% endif %}\n{% endfor %}\n    return 0;\n}',NULL,NULL,NULL,NULL,NULL,'','None',0,'{}',1,1,0,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'none',0,0,10240,'','',1,0,NULL),
(118,118,'python3',0,1,0,0,0,3,60,'# Enter an integer testcase',NULL,1,'','0',1,NULL,NULL,'import pymysql\nimport sys\nDB_HOST = \"mariadb\"\nDB_USER = \"jobe_user\"\nDB_PASS = \"JobeSecret123!\"\nDB_NAME = \"testcase_store\"\ncourse_id = \"{{ COURSE.shortname | default(\'CS101\') }}\"\nquestion_id = {{ QUESTION.id | default(100) }}\nstudent_id = \"{{ STUDENT.username | default(\'student\') }}\"\nstudent_input = \"\"\"{{ STUDENT_ANSWER | e(\'py\') }}\"\"\".strip()\njobe_server = open(\"/etc/hostname\").read().strip()\nconn = pymysql.connect(host=DB_HOST, user=DB_USER, password=DB_PASS, database=DB_NAME)\ncur = conn.cursor()\ncur.execute(\"SELECT student_id, jobe_server FROM student_testcases WHERE course_id=%s AND question_id=%s AND test_input=%s\", (course_id, question_id, student_input))\nexist = cur.fetchone()\nif exist:\n    print(\"Duplicate testcase: already submitted by \" + exist[0] + \".\")\n    conn.close()\n    sys.exit(0)\ncur.execute(\"INSERT INTO student_testcases (course_id, question_id, student_id, test_input, jobe_server) VALUES (%s, %s, %s, %s, %s)\", (course_id, question_id, student_id, student_input, jobe_server))\nconn.commit()\nprint(\"Unique testcase stored successfully on \" + jobe_server + \".\")\nconn.close()',NULL,NULL,NULL,NULL,NULL,NULL,'twig',0,NULL,0,1,0,NULL,NULL,NULL,'jobesandbox',NULL,NULL,NULL,NULL,NULL,0,0,0,NULL,NULL,1,0,NULL),
(119,119,'python3',0,1,0,0,0,3,80,'def is_prime(n):\n    \"\"\"\n    Hàm kiểm tra số nguyên n có phải số nguyên tố hay không (True/False).\n    Hãy viết giải thuật hoàn chỉnh để vượt qua tất cả các trường hợp kiểm thử.\n    \"\"\"\n    if n <= 1:\n        return False\n    for i in range(2, int(n**0.5) + 1):\n        if n % i == 0:\n            return False\n    return True\n',NULL,1,'0','def is_prime(n):\n    if n <= 1:\n        return False\n    for i in range(2, int(n**0.5) + 1):\n        if n % i == 0:\n            return False\n    return True\n',1,NULL,NULL,'import sys\n\nstudent_submission = \"\"\"{{ STUDENT_ANSWER | e(\'py\') }}\"\"\"\nteacher_solution = \"\"\"{{ QUESTION.answer | e(\'py\') }}\"\"\"\n\n# Chạy code sinh viên\nstudent_env = {}\ntry:\n    exec(student_submission, student_env)\nexcept Exception as e:\n    print(f\"Lỗi cú pháp / Runtime Error: {e}\")\n    sys.exit(0)\n\nif \"is_prime\" not in student_env or not callable(student_env[\"is_prime\"]):\n    print(\"Không tìm thấy định nghĩa hàm is_prime(n)!\")\n    sys.exit(0)\n\nstudent_fn = student_env[\"is_prime\"]\n\n# Chạy code thầy cô (Oracle)\nteacher_env = {}\nexec(teacher_solution, teacher_env)\nteacher_fn = teacher_env[\"is_prime\"]\n\n# Tập testcase chạy đối chiếu vi sai\ntest_inputs = [2, 3, 4, 5, 1, 0, -5, 17, 49, 97, 100]\nfor n in test_inputs:\n    expected = teacher_fn(n)\n    try:\n        actual = student_fn(n)\n        if actual != expected:\n            print(f\"Chưa chính xác tại n = {n}. Lời giải của thầy cô trả về: {expected}, nhưng code của bạn trả về: {actual}\")\n            sys.exit(0)\n    except Exception as e:\n        print(f\"Lỗi Crash tại n = {n}: {e}\")\n        sys.exit(0)\n\nprint(\"All tests passed! Code của bạn hoàn toàn chính xác khi đối chiếu với lời giải mẫu.\")\n',NULL,NULL,NULL,NULL,NULL,'','None',0,'',0,1,0,NULL,'python3',NULL,'jobesandbox',NULL,'EqualityGrader',NULL,NULL,NULL,0,0,0,NULL,NULL,1,0,NULL),
(120,120,'python3',0,1,0,0,0,3,80,'def is_palindrome(s):\n    \"\"\"\n    Hàm kiểm tra chuỗi s có phải là chuỗi đối xứng (Palindrome) hay không (True/False).\n    \"\"\"\n    return s == s[::-1]\n',NULL,1,'0','def is_palindrome(s):\n    return s == s[::-1]\n',1,NULL,NULL,'import sys\n\nstudent_submission = \"\"\"{{ STUDENT_ANSWER | e(\'py\') }}\"\"\"\nteacher_solution = \"\"\"{{ QUESTION.answer | e(\'py\') }}\"\"\"\n\nstudent_env = {}\ntry:\n    exec(student_submission, student_env)\nexcept Exception as e:\n    print(f\"Lỗi cú pháp / Runtime Error: {e}\")\n    sys.exit(0)\n\nif \"is_palindrome\" not in student_env or not callable(student_env[\"is_palindrome\"]):\n    print(\"Không tìm thấy định nghĩa hàm is_palindrome(s)!\")\n    sys.exit(0)\n\nstudent_fn = student_env[\"is_palindrome\"]\n\nteacher_env = {}\nexec(teacher_solution, teacher_env)\nteacher_fn = teacher_env[\"is_palindrome\"]\n\ntest_inputs = [\"radar\", \"racecar\", \"hello\", \"world\", \"noon\", \"level\", \"madam\", \"12321\", \"abccba\"]\nfor s in test_inputs:\n    expected = teacher_fn(s)\n    try:\n        actual = student_fn(s)\n        if actual != expected:\n            print(f\"Chưa chính xác tại s = \\\"{s}\\\". Lời giải của thầy cô trả về: {expected}, nhưng code của bạn trả về: {actual}\")\n            sys.exit(0)\n    except Exception as e:\n        print(f\"Lỗi Crash tại s = \\\"{s}\\\": {e}\")\n        sys.exit(0)\n\nprint(\"All tests passed! Code của bạn hoàn toàn chính xác khi đối chiếu với lời giải mẫu.\")\n',NULL,NULL,NULL,NULL,NULL,'','None',0,'',0,1,0,NULL,'python3',NULL,'jobesandbox',NULL,'EqualityGrader',NULL,NULL,NULL,0,0,0,NULL,NULL,1,0,NULL);
